CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, avatar BYTEA, avatar_version TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT NOT NULL, address TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, kcal NUMERIC NOT NULL, protein NUMERIC NOT NULL, fat NUMERIC NOT NULL, carbs NUMERIC NOT NULL, user_id INTEGER REFERENCES users(id), is_builtin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS portions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, grams NUMERIC NOT NULL, user_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS diary (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), day TEXT NOT NULL, meal TEXT NOT NULL, grams NUMERIC NOT NULL, portion_name TEXT NOT NULL, user_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS activities (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day TEXT NOT NULL, name TEXT NOT NULL, kcal NUMERIC NOT NULL, user_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS profile (user_id INTEGER PRIMARY KEY REFERENCES users(id), sex TEXT NOT NULL, age INTEGER NOT NULL, height NUMERIC NOT NULL, weight NUMERIC NOT NULL, activity TEXT NOT NULL, goal TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migration_state (name TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS diary_user_day ON diary(user_id,day);
CREATE INDEX IF NOT EXISTS activities_user_day ON activities(user_id,day);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
